// Concatenates supabase/migrations/*.sql into supabase/setup.sql (one paste in the SQL editor).
//   node scripts/build-setup-sql.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
const dir = new URL('../supabase/migrations/', import.meta.url)
const parts = readdirSync(dir).filter((f) => f.endsWith('.sql')).sort().map((f) => `-- ▸ ${f}\n${readFileSync(new URL(f, dir), 'utf8')}`)
writeFileSync(
  new URL('../supabase/setup.sql', import.meta.url),
  `-- ════════════════════════════════════════════════════════════════════
--  SKYHIGH — ONE-TIME SUPABASE SETUP   (generated by scripts/build-setup-sql.mjs)
--
--  1. Change the email on the LAST LINE to the owner's email address.
--  2. Supabase dashboard → SQL Editor → New query → paste this whole file → Run.
--  3. Authentication → Users → Add user (that email + a password, Auto Confirm), then sign in at <your-site>/admin.
--
--  Safe to run again after updates.
-- ════════════════════════════════════════════════════════════════════

${parts.join('\n\n')}

-- ── First owner ─────────────────────────────────────────────────────
-- ▼▼▼ CHANGE THIS EMAIL ▼▼▼
insert into public.admin_invites (email, role) values (lower('owner@example.com'), 'admin')
on conflict (email) do update set role = 'admin';
`,
)
console.log('supabase/setup.sql updated')
